 * 
 * Example 1:
 * 
 * Input: 
 * ["test.email+alex@leetcode.com","test.e.mail+bob.cathy@leetcode.com","testemail+david@lee.tcode.com"
 * ]
 * Output: 2
 * Explanation: "testemail@leetcode.com" and "testemail@lee.tcode.com" actually receive mails
 * 
 * Note:
 * 
 * 	1 <= emails[i].length <= 100
 * 	1 <= emails.length <= 100
 * 	Each emails[i] contains exactly one '@' character.
 * 	All local and domain names are non-empty.
 * 	Local names do not start with a '+' character.
 * 
 ******************************************************************************************************/
class Solution {
  public int numUniqueEmails(String[] emails) {
	int numOfEmails = emails.length;
	for (int i = 0; i < numOfEmails; i++) {
		int numOfCharacters = emails[i].length();
		int indexOfAt = emails[i].indexOf("@");
		int indexOfPlus = emails[i].indexOf("+");
		String localName = emails[i].substring(0, indexOfAt);
		String domainName = emails[i].substring(indexOfAt + 1, numOfCharacters);
		if (indexOfPlus != -1) {
			localName = localName.substring(0, indexOfPlus);
		}
		localName = localName.replace(".", "");
		emails[i] = localName + "@" + domainName;
	}
	return (int) Arrays.asList(emails)
		.stream()
		.distinct()
		.count();
}
}
